class ProcessingError(Exception):
    def __init__(self, executor, experiment, model, image, label, class_id, image_size):
        super().__init__(f"Error processing {str(label):20s}")
        self.executor = executor
        self.experiment = experiment
        self.model = model
        self.image = image
        self.label = label
        self.class_id = class_id
        self.image_size = image_size


def _saliency_to_point(saliency):
    assert len(saliency.shape) == 4
    w = saliency.shape[3]
    point = torch.argmax(
        saliency.view(len(saliency), -1),
        dim=1,
        keepdim=True
    )
    return torch.cat((point % w, point // w), dim=1)


class ExperimentExecutor():

    def __init__(self, experiment, chunk=None, debug=0, log=0, seed=seed):
        self.experiment = experiment
        self.device = None
        self.model = None
        self.model_to_infer = None
        self.data = None
        self.loader = None
        self.pointing = None
        self.pointing_difficult = None
        self.debug = debug
        self.log = log
        self.seed = seed

        self.experiment.sensitivities = []

        if self.experiment.arch == 'vgg16':
            self.gradcam_layer = 'features.29'  # relu before pool5
            self.saliency_layer = 'features.23'  # pool4
            self.contrast_layer = 'classifier.4'  # relu7
        elif self.experiment.arch == 'resnet50':
            self.gradcam_layer = 'layer4'
            self.saliency_layer = 'layer3'  # 'layer3.5'  # res4a
            self.contrast_layer = 'avgpool'  # pool before fc layer
        else:
            assert False

        if self.experiment.dataset == 'voc_2007':
            subset = 'test'
        elif self.experiment.dataset == 'coco':
            subset = 'val2014'
        else:
            assert False

        # Load the model.
        if self.experiment.method in ["rise", "adaptive_rise", "smbo", 'extremal_perturbation']:
            input_size = (224, 224)
        else:
            input_size = 224
        transform = get_transform(size=input_size,
                                  dataset=self.experiment.dataset)

        self.data = get_dataset(name=self.experiment.dataset,
                                subset=subset,
                                transform=transform,
                                download=False,
                                limiter=LIMITER)

        # Get subset of data. This is used for debugging and for
        # splitting computation on a cluster.
        if chunk is None:
            chunk = self.experiment.chunk

        if isinstance(chunk, dict):
            dataset_filter = chunk
            chunk = []
            if 'image_name' in dataset_filter:
                for i, name in enumerate(self.data.images):
                    if dataset_filter['image_name'] in name:
                        chunk.append(i)

            print(f"Filter selected {len(chunk)} image(s).")

         # Liimit the chunk to the actual size of the dataset.
        if chunk is not None:
            chunk = list(set(range(len(self.data))).intersection(set(chunk)))

        # Extract the data subset.
        chunk = Subset(self.data, chunk) if chunk is not None else self.data

        if run_experiment:
            # Shuffle with seed
            shuffle = True
            worker_init_fn = np.random.seed(0)
        else:
            shuffle = False
            worker_init_fn = None

        # Get a data loader for the subset of data just selected.
        self.loader = DataLoader(chunk,
                                 batch_size=1,
                                 num_workers=0,
                                 collate_fn=self.data.collate,
                                 shuffle=shuffle,
                                 worker_init_fn=worker_init_fn
                                 )

        self.pointing = PointingGameBenchmark(self.data, difficult=False)
        self.pointing_difficult = PointingGameBenchmark(
            self.data, difficult=True)

        self.del_auc_history = []
        self.ins_auc_history = []

        self.data_iterator = iter(self.loader)

    def _lazy_init(self):
        if self.device is not None:
            return

        if self.log:
            from torchray.benchmark.logging import mongo_connect
            self.db = mongo_connect(self.experiment.series)

        self.device = get_device()
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False

        self.model = get_model(
            arch=self.experiment.arch,
            dataset=self.experiment.dataset,
            convert_to_fully_convolutional=True,
        )

        # Some methods require patching the models further for
        # optimal performance.
        if self.experiment.arch == 'resnet50':
            if any([e in self.experiment.method for e in [
                    'contrastive_excitation_backprop',
                    'deconvnet',
                    'excitation_backprop',
                    'grad_cam',
                    'gradient',
                    'guided_backprop'
            ]]):
                # self.model_to_infer = get_model(
                #     arch=self.experiment.arch,
                #     dataset=self.experiment.dataset,
                #     convert_to_fully_convolutional=True,
                # )
                # self.model_to_infer.eval()
                # self.model_to_infer.to(self.device)
                self.model.avgpool = torch.nn.AvgPool2d((7, 7), stride=1)

            if 'excitation_backprop' in self.experiment.method:
                # Replace skip connection with EltwiseSum.
                self.model = update_resnet(self.model, debug=True)

        # Change model to eval modself.
        self.model.eval()

        # Move model to device.
        self.model.to(self.device)

    def __iter__(self):
        return self

    def __len__(self):
        return len(self.loader.dataset)

    def _default_perturb_func(self,
            input, perturb_radius: float = 0.02
    ):
        perturbed_input = (input + torch.FloatTensor(input.size())
                           .uniform_(-perturb_radius, perturb_radius)
                           .to(input.device))
        return perturbed_input

    def _get_sensitivity(self, explanation_func, expl_inputs, x, current_n_perturb_samples=5):
        expl_inputs = explanation_func(x)
        expl_inputs = expl_inputs.unsqueeze(0).unsqueeze(0)
        expl_inputs_expanded = tuple(expl_inputs.repeat_interleave(current_n_perturb_samples, dim=0))

        expl_perturbed_inputs = []
        for _ in range(current_n_perturb_samples):
            x_perturbed = self._default_perturb_func(x)
            expl_perturbed = explanation_func(x_perturbed)
            expl_perturbed_inputs.append(expl_perturbed.unsqueeze(0))
        expl_perturbed_inputs = tuple(expl_perturbed_inputs)

        expl_inputs_expanded_np = [item.cpu().numpy() for item in expl_inputs_expanded]
        expl_perturbed_inputs_np = [item.cpu().numpy() for item in expl_perturbed_inputs]

        sensitivities = torch.cat(
            [
                (expl_input - expl_perturbed).view(expl_perturbed.size(0), -1)
                for expl_perturbed, expl_input in zip(
                    expl_perturbed_inputs, expl_inputs_expanded
                )
            ],
            dim=1,
        )

        # compute the norm of original input explanations
        expl_inputs_norm_expanded = torch.norm(
            torch.cat(
                [expl_input.view(expl_input.size(0), -1) for expl_input in expl_inputs],
                dim=1,
            ),
            p="fro",
            dim=1,
            keepdim=True,
        ).repeat_interleave(current_n_perturb_samples, dim=0)
        expl_inputs_norm_expanded = torch.where(
            expl_inputs_norm_expanded == 0.0,
            torch.tensor(
                1.0,
                device=expl_inputs_norm_expanded.device,
                dtype=expl_inputs_norm_expanded.dtype,
            ),
            expl_inputs_norm_expanded,
        )

        # compute the norm for each input noisy example
        sensitivities_norm = (
            torch.norm(sensitivities, p="fro", dim=1, keepdim=True)
            / expl_inputs_norm_expanded
        )

        def max_values(input_tnsr):
            return torch.max(input_tnsr, dim=1).values

        bsz = 1
        res = max_values(sensitivities_norm.view(bsz, -1))

        a = 1

