    def aggregate(self, results):
        for class_id, hit in results['pointing'].items():
            self.pointing.aggregate(hit, class_id)
        for class_id, hit in results['pointing_difficult'].items():
            self.pointing_difficult.aggregate(hit, class_id)

    def deletion_insertion_single_run(self, x: torch.tensor, saliency: np.array, class_id: int, inherit_hw_from_input: bool = False) -> Tuple[float, float]:
        klen = 11
        ksig = 5
        kern = gkern(klen, ksig)

        # Function that blurs input image
        blur = lambda x: F.conv2d(x, kern.cuda(), padding=klen // 2)

        insertion = CausalMetric(self.model, 'ins', 224, substrate_fn=blur, inherit_hw_from_input=inherit_hw_from_input)
        deletion = CausalMetric(self.model, 'del', 224, substrate_fn=torch.zeros_like, inherit_hw_from_input=inherit_hw_from_input)

        h_del = deletion.single_run(x, saliency, verbose=0,
                                    class_id=class_id)  # , save_to='/home/etsykuno/tmp/'
        h_ins = insertion.single_run(x, saliency, verbose=0,
                                     class_id=class_id)  # , save_to='/home/etsykuno/tmp/'

        h_del_auc = auc(h_del)
        h_ins_auc = auc(h_ins)
        return h_del_auc, h_ins_auc

    def run(self, save=True):
        all_results = []
        for itr, results in enumerate(self):
            if results is None:
                continue
            all_results.append(results)
            self.aggregate(results)
            if itr % max(len(self) // 20, 1) == 0 or itr == len(self) - 1:
                print("[{}/{}]".format(itr + 1, len(self)))
                print(self)

        print("[final result]")
        print(self)

        self.experiment.pointing = self.pointing.accuracy
        self.experiment.pointing_difficult = self.pointing_difficult.accuracy
        if save:
            self.experiment.save()

        self.experiment.del_auc_history = np.array(self.del_auc_history)
        self.experiment.ins_auc_history = np.array(self.ins_auc_history)

        return all_results

    def __str__(self):
        return (
            f"{self.experiment.method}, {self.experiment.arch}, "
            f"{self.experiment.dataset} "
            # f"pointing_game: {self.pointing}\n"
            # f"{self.experiment.method} {self.experiment.arch} "
            # f"{self.experiment.dataset} "
            # f"pointing_game(difficult): {self.pointing_difficult}\n"
            # f"loc_det method - {loc_det_method}\n"
            # f"num_ep_iterations - {num_ep_iterations}"
        )


